# Generated by build.py from recipe.yml for recipe https-run-an-https-proxy. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout proxy.key -out proxy.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout origin.key -out origin.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--directory', 'site', 'http://127.0.0.1:8080/', 'https://127.0.0.1:8081/', '--cert', 'origin.pem', '--key', 'origin.key' -PassThru -NoNewWindow
$server1 = Start-Process surl -ArgumentList '--proxy', 'https://127.0.0.1:8082/', '--cert', 'proxy.pem', '--key', 'proxy.key', '-v', '--log-file', 'proxy.log' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS --proxy-cacert proxy.pem -x https://127.0.0.1:8082/ http://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0; Stop-Process $server1 }
